  isProductPinFeed
  showCreator
  subtitle
  title
  videoPin {
    entityId
    videos {
      videoList {
        v720P {
          height
          thumbnail
          url
          width
        }
      }
      id
    }
    id
  }
}

fragment TodayTabPagination_query on Query {
  v3RecommendedTodayArticlesQuery(numDays: 3) {
    __typename
    ... on V3RecommendedTodayArticles {
      data {
        __typename
        ... on V3RecommendedTodayArticlesDataConnectionContainer {
          connection(first: 50) {
            edges {
              node {
                __typename
                ...TodayTabStory
                ...TodayArticleModule
              }
              cursor
            }
            pageInfo {
              endCursor
              hasNextPage
            }
          }
        }
      }
    }
  }
}

fragment TodayTabStory on Story {
  __typename
  storyTitle: title {
    format
  }
  storySubTitle: subtitle {
    format
  }
  storyType
}
